from jsonb_to_recordset($json$[{"id":"che-so-261","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The van’t Hoff factor i is the ratio of","options":["the observed colligative effect to the effect calculated for no ionisation","molarity to molality","$K_H$ to p","$K_b$ to $K_f$"],"answer_index":0,"explanation":"i = $\\Delta T_{\\mathrm{obs}} / \\Delta T_{\\mathrm{calc}}$ (and likewise for $\\pi$ or relative lowering).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-262","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For a non-electrolyte that neither associates nor dissociates, i is","options":["1","0","2","0.5"],"answer_index":0,"explanation":"One formula unit still gives one particle, so the factor is unity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-263","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Complete dissociation of K2SO4 in water gives i equal to","options":["3","2","1","4"],"answer_index":0,"explanation":"K2SO4 → 2 K⁺ + SO₄²⁻, three ions, so i = 3 when $\\alpha = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-264","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Association of solute molecules makes the observed molar mass","options":["larger than the true formula mass","smaller than the true formula mass","unchanged","zero"],"answer_index":0,"explanation":"Fewer particles are present, so the colligative effect is smaller and $M_{\\mathrm{obs}} = M / i$ is larger (i < 1).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-265","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissociation of a solute makes the observed molar mass","options":["smaller than the true formula mass","larger than the true formula mass","infinite","equal to $K_b$"],"answer_index":0,"explanation":"More particles raise the colligative effect, so $M_{\\mathrm{obs}} = M / i$ falls below M.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-266","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Abnormal molar mass arises when","options":["the solute associates or dissociates","the solvent is merely wet","the temperature is 25 °C","$K_H$ is large"],"answer_index":0,"explanation":"Either process changes the particle count, so the molar mass inferred from a colligative law is abnormal.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-267","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The relation connecting i, the number of particles n from one formula unit, and the degree of dissociation $\\alpha$ is","options":["$i = 1 + (n - 1)\\alpha$","$i = n\\alpha$","$i = 1 - n\\alpha$","$i = \\alpha / n$"],"answer_index":0,"explanation":"Each dissociated unit adds (n − 1) extra particles, so i − 1 = (n − 1)$\\alpha$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-268","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Benzoic acid in benzene often shows i less than 1 because it","options":["dimerises","ionises into four ions","evaporates completely","becomes a metal"],"answer_index":0,"explanation":"Hydrogen-bonded dimers reduce the particle count, so i < 1 and $M_{\\mathrm{obs}}$ is high.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-269","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For Al2(SO4)3, complete dissociation would give i of","options":["5","3","2","4"],"answer_index":0,"explanation":"2 Al³⁺ + 3 SO₄²⁻ = five ions per formula unit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-270","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"If i = 2 for a binary electrolyte AB, the degree of dissociation is","options":["1 (complete)","0.5","0","2"],"answer_index":0,"explanation":"i = 1 + (2 − 1)$\\alpha$ = 1 + $\\alpha$, so i = 2 means $\\alpha = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
